import random
import os
import glob

import numpy as np
import pyhmmer
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

from HAMMER import aa_log_probs_to_hmm_file


def generate_test_matrix(input: str, prob: float = 0.7) -> np.ndarray:
    mapping = {'A': 0, 'R': 1, 'N': 2, 'D': 3, 'C': 4, 'Q': 5, 'E': 6, 'G': 7, 'H': 8, 'I': 9,
               'L': 10, 'K': 11, 'M': 12, 'F': 13, 'P': 14, 'S': 15, 'T': 16, 'W': 17, 'Y': 18, 'V': 19,}
    length = len(input)
    test_array = np.zeros((length, 28), dtype=np.float32)
    test_array[:] = (1-prob)/27
    for i in range(length):
        test_array[i,mapping[input[i]]] = prob
    # Clip values to avoid log(0)
    test_array = np.clip(test_array, 1e-7, 1.0)
    return np.log(test_array)

def random_substrings(s: str, length: int, num: int = 1000) -> tuple:
    substrings = tuple(
        s[start:start + length]
        for start in [random.randint(0, len(s) - length) for _ in range(num)]
    )
    return substrings

if __name__ == "__main__":
    test_name = "PF3D7_1408700.1"
    test_seq = ""
    tests = 1000
    lengths = [i for i in range(10, 21)]
    confidences = np.round(np.arange(0.7, 1.0, 0.05, dtype=float), 2)
    temp_path = "E_HMMER_searching/benchmarking/temp/"
    os.makedirs("E_HMMER_searching/benchmarking/csv/", exist_ok=True)
    os.makedirs(temp_path, exist_ok=True)

    csv = False
    if csv:
        alphabet = {
        "amino": pyhmmer.easel.Alphabet.amino(),
        "RNA": pyhmmer.easel.Alphabet.rna(),
        "DNA": pyhmmer.easel.Alphabet.dna(),
        }["amino"]
        with pyhmmer.easel.SequenceFile('E_HMMER_searching/search_pool.fasta', alphabet=alphabet, digital=True) as sf:
            seq_pool = sf.read_block()

        for length in lengths:
            seqs = random_substrings(test_seq, length, tests)
            for c in confidences:
                files = []
                for test in range(tests):
                    hmm_file = temp_path + f"{test_name}_{length}_{c}_{test}.hmm"
                    aa_log_probs_to_hmm_file(
                        name=f"{test_name}_{length}_{c}_{test}",
                        aa_log_probs=generate_test_matrix(seqs[test]),
                        confidence=[c] * length,
                        output_path=hmm_file,
                        alphabet_type='amino'
                    )
                    files.append(hmm_file)

                hmms = [
                    (os.path.basename(f).split(".hmm")[0], pyhmmer.plan7.HMMFile(f).read())
                    for f in files
                ]
                all_hits = pyhmmer.hmmer.hmmsearch([hmm for _, hmm in hmms], seq_pool)
                for f in files:
                    if os.path.exists(f):
                        os.remove(f)

                hits_csv = {
                    "target_name": [],
                    "query_name": [],
                    "accession": [],
                    "E-value": [],
                    "score": [],
                    "bias": [],
                    "description": [],
                }
                for hits, name in zip(all_hits, [name for name, _ in hmms]):
                    # with open('E_HMMER_searching/test_files_pyhmmer/hits.hhr', 'wb') as f:
                    #     hits.write(f)
                    if len(hits) == 0:
                        continue
                    else:
                        for hit in hits:
                            if hit.evalue < 1e-3:
                                hits_csv["target_name"].append(hit.name.decode("utf-8") if hit.name else "")
                                hits_csv["query_name"].append(os.path.basename(name).split('.hmm')[0])
                                hits_csv["accession"].append(hit.accession.decode("utf-8") if hit.accession else "")
                                hits_csv["E-value"].append(hit.evalue if hit.evalue else "")
                                hits_csv["score"].append(hit.score if hit.score else "")
                                hits_csv["bias"].append(hit.bias if hit.bias else "")
                                hits_csv["description"].append(hit.description.decode("utf-8") if hit.description else "")

                hits_df = pd.DataFrame(hits_csv)
                hits_df.to_csv(f'E_HMMER_searching/benchmarking/csv/hits_{length}_{c}.csv', index=False)
    
    table = True
    if table:
        table_data = pd.DataFrame(index=confidences, columns=lengths)
        for f in glob.glob("E_HMMER_searching/benchmarking/csv/hits_*.csv"):
            df = pd.read_csv(f)
            f = os.path.basename(f)
            length = int(f.split("_")[1])
            confidence = float(f.split("_")[2].split(".csv")[0])
            hits = float(len(df) / tests) 
            table_data.at[confidence, length] = hits
        table_data.to_csv("E_HMMER_searching/benchmarking/benchmark_table.csv")

        # Draw color map (heatmap)
        plt.figure(figsize=(10, 6))
        sns.heatmap(
            table_data.astype(float), 
            annot=True,
            fmt=".1%",
            cmap="crest")
        plt.title("HMMER Benchmark", fontsize=25)
        plt.xlabel("Query Length", fontsize=20)
        plt.ylabel("Averaged Confidence", fontsize=20)
        plt.xticks(fontsize=15)
        plt.yticks(fontsize=15)
        plt.tight_layout()
        plt.savefig("E_HMMER_searching/benchmarking/benchmark_table_heatmap.png", dpi=300)